{
  "eventSource": "rds.amazonaws.com",
  "eventName": "DeleteDBInstance",
  "awsRegion": "us-east-1",
  "errorCode": "AccessDenied",
  "errorMessage": "User: arn:aws:sts::333333333333:assumed-role/Operador/sessao is not authorized to perform: rds:DeleteDBInstance with an explicit deny in a service control policy",
  "requestParameters": {
    "dBInstanceIdentifier": "cadencia-prod"
  },
  "recipientAccountId": "333333333333"
}

// VerificadorFronteira/Program.cs — prova a fronteira sem tocar em dado real
//
// Chama iam:SimulatePrincipalPolicy nas duas contas, para a MESMA acao, e
// imprime lado a lado. Segundo a documentacao da AWS, o simulador avalia SCP
// com logica "consciente do servico" — por isso o resultado diverge entre as
// contas sem nenhuma chamada destrutiva de verdade ter sido executada.

using Amazon.IdentityManagement;
using Amazon.IdentityManagement.Model;
using Amazon.SecurityToken;
using Amazon.SecurityToken.Model;

var acoes = new List<string> { "rds:DeleteDBInstance", "rds:DeleteDBCluster" };

var contas = new[]
{
    new { Nome = "Não-Produção", RoleArn = Ambiente("ROLE_NAO_PRODUCAO") },
    new { Nome = "Produção",     RoleArn = Ambiente("ROLE_PRODUCAO") },
};

foreach (var conta in contas)
{
    // Assume a role NA CONTA ALVO — o simulador roda com as credenciais
    // dessa conta, entao ele enxerga a SCP que se aplica especificamente a
    // ela, e nao a de outra conta da organizacao.
    using var sts = new AmazonSecurityTokenServiceClient();
    var assumida = await sts.AssumeRoleAsync(new AssumeRoleRequest
    {
        RoleArn         = conta.RoleArn,
        RoleSessionName = "verificador-fronteira",
    });

    using var iam = new AmazonIdentityManagementServiceClient(
        assumida.Credentials.AccessKeyId,
        assumida.Credentials.SecretAccessKey,
        assumida.Credentials.SessionToken);

    var resposta = await iam.SimulatePrincipalPolicyAsync(new SimulatePrincipalPolicyRequest
    {
        PolicySourceArn = conta.RoleArn,
        ActionNames     = acoes,
        // Recurso curinga: o alvo da prova e o TETO da conta, nao um banco
        // especifico. Para provar contra um recurso real, troque por um ARN.
        ResourceArns    = new List<string> { "*" },
    });

    Console.WriteLine($"— {conta.Nome} —");
    foreach (var resultado in resposta.EvaluationResults)
    {
        // EvalDecision vem como "allowed", "explicitDeny" ou "implicitDeny".
        // Na conta de Producao, espera-se explicitDeny — a SCP se
        // manifestando, mesmo que a role tenha AmazonRDSFullAccess.
        Console.WriteLine($"  {resultado.EvalActionName}: {resultado.EvalDecision}");
    }
}

static string Ambiente(string nome) =>
    Environment.GetEnvironmentVariable(nome)
    ?? throw new InvalidOperationException($"defina a variável {nome} com o ARN da role a testar");
